                        const relatedTargetId = relatedTarget && 'id' in relatedTarget && typeof relatedTarget.id === 'string' && relatedTarget.id;
                        // We delay the validation in order to prevent Checkbox loss of focus when
                        // the user is focusing a TextInput and proceeds to toggle a CheckBox in
                        // web and mobile web platforms.

                        setTimeout(() => {
                            if (
                                relatedTargetId === CONST.OVERLAY.BOTTOM_BUTTON_NATIVE_ID ||
                                relatedTargetId === CONST.OVERLAY.TOP_BUTTON_NATIVE_ID ||
                                relatedTargetId === CONST.BACK_BUTTON_NATIVE_ID
                            ) {
                                return;
                            }
                            setTouchedInput(inputID);
                            // We don't validate the form on blur in case the current screen is not focused
                            if (shouldValidateOnBlur && isFocusedRef.current) {
                                onValidate(inputValues, !hasServerError);
                            }
                        }, VALIDATE_DELAY);
                    }
                    inputProps.onBlur?.(event);
                },
                onInputChange: (value, key) => {
                    const inputKey = key ?? inputID;

                    setInputValues((prevState) => {
                        const newValues = {...prevState, [inputKey]: value};

                        if (shouldValidateOnChange) {
                            onValidate(newValues, !hasServerError);
                        }

                        // We delay the draft update to prevent the re-rendering of the FormProvider
                        // from interrupting the user's input.
                        setTimeout(() => {
                            const newDraftValue: Record<string, unknown> = {};
                            Object.keys(inputRefs.current).forEach((k) => {
                                if (inputRefs.current[k].props.shouldSaveDraft) {
                                    newDraftValue[k] = newValues[k];
                                }
                            });
                            FormActions.setDraftValues(formID, newDraftValue);
                        }, VALIDATE_DELAY);
                        return newValues;
                    });

                    inputProps.onInputChange?.(value);
                },
            };
        },
        [formState, draftValues, inputValues, errors, hasServerError, onValidate, submit, setTouchedInput, shouldValidateOnBlur, shouldValidateOnChange, formID],
    );

    const providerValue = useMemo(() => ({registerInput, inputValues, formState}), [registerInput, inputValues, formState]);

    return (
        <FormContext.Provider value={providerValue}>
            <FormWrapper
                formID={formID}
                onSubmit={submit}
                // eslint-disable-next-line react/jsx-props-no-spreading
                {...rest}
            >
                {typeof children === 'function' ? children({inputValues}) : children}
            </FormWrapper>
        </FormContext.Provider>
    );
}

FormProvider.displayName = 'FormProvider';

export default forwardRef(FormProvider);

